<section class="sec sec-tool"><div class="wrap"><h2 class="sr-only">Holdback Recovery Calculator</h2><div class="rv">
<div class="tool tool-wide" data-tool="dep">
  <div class="tool-head"><span>Holdback recovery calculator</span><i>Add as many items as you need</i></div>
  <div class="tool-body">
    <div class="tool-in">
      <div class="table-wrap items-table"><table><thead><tr><th>Item</th><th>Replacement cost ($)</th><th>Age (yrs)</th><th>Life (yrs)</th><th>ACV</th><th><span class="sr-only">Remove</span></th></tr></thead><tbody>
      <tr><td><input name="item" value="Laminated shingle roof" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="16200" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="8" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="30" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Steel siding — two elevations" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="5400" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="15" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="40" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Seamless gutters" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="1650" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="12" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="25" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr>
      </tbody></table></div>
      <div class="btn-row"><button type="button" class="btn ghost small" data-add data-run>+ Add item</button></div>
      <div class="row2">
        <div><label for="d-ded">Deductible ($)</label><input id="d-ded" name="deduct" inputmode="decimal" value="2500"></div>
        <div><label for="d-cap">Maximum depreciation</label><select id="d-cap" name="cap"><option value="50">50%</option><option value="70">70%</option><option value="80" selected>80%</option><option value="90">90%</option></select><span class="hint">Many estimates cap depreciation; check yours.</span></div>
      </div>
      <label class="check"><input type="checkbox" name="nonrec"> My policy pays actual cash value only (no recoverable depreciation)</label>
    </div>
    <div class="tool-out" aria-live="polite" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr))">
      <div class="out-big"><small>First check (ACV − deductible)</small><b data-o="first">$0</b></div>
      <div class="out-big"><small>Held back until repairs</small><b data-o="held">$0</b></div>
